import {useCallback,useEffect,useMemo,useState} from 'react';
import {CalendarDays,CheckCircle2,ChevronRight,Loader2,Plus,RefreshCw} from 'lucide-react';
import {createPracticeResource,listPracticeResources,updatePracticeResource} from '../../lib/practiceOperationsApi';

const CONFIG={
  consultations:{resource:'consultations',title:'Consultations',empty:'No consultations are scheduled.',create:'Schedule consultation',type:'STANDARD',status:'SCHEDULED'},
  followups:{resource:'follow-ups',title:'Follow-ups',empty:'No follow-ups are due.',create:'Create follow-up',type:'CLIENT_FOLLOWUP',status:'TODO'},
  goals:{resource:'goals',title:'Goals & progress',empty:'No client goals have been recorded.',create:'Add goal',type:'CUSTOM',status:'TODO'},
  tasks:{resource:'tasks',title:'Tasks',empty:'No practice tasks are open.',create:'Create task',type:'CUSTOM',status:'TODO'},
  checkins:{resource:'check-ins',title:'Weekly check-ins',empty:'No weekly check-ins have been submitted.',create:'Record check-in',type:'WEEKLY',status:'COMPLETED'},
  adherence:{resource:'adherence',title:'Client adherence',empty:'No adherence updates are available.',create:'Record adherence',type:'DIET_PLAN',status:'NOT_REPORTED'},
  notes:{resource:'notes',title:'Client notes',empty:'No client notes have been added.',create:'Add private note',type:'PRIVATE_NOTE',status:'ACTIVE'},
};

export function ExternalCareOperations({view,clients=[]}){
  const config=CONFIG[view];const [page,setPage]=useState({items:[],next_cursor:null});const [state,setState]=useState('loading');const [error,setError]=useState('');const [open,setOpen]=useState(false);
  const load=useCallback(async()=>{if(!config)return;setState('loading');setError('');try{setPage(await listPracticeResources(config.resource));setState('ready');}catch(reason){setError(reason.message);setState('error');}},[config]);
  useEffect(()=>{void load();},[load]);
  const grouped=useMemo(()=>page.items.reduce((result,item)=>{(result[item.status]??=[]).push(item);return result;},{}),[page.items]);
  if(!config)return null;
  return <div className="space-y-6 pb-24 lg:pb-8"><header className="flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><p className="text-xs font-bold uppercase tracking-[.16em] text-blue-700">Practice operations</p><h2 className="mt-2 text-3xl font-bold tracking-tight">{config.title}</h2><p className="mt-2 text-sm text-slate-600">Tenant-scoped care work with audit-safe updates.</p></div><button onClick={()=>setOpen(true)} className="hidden min-h-11 rounded-xl bg-blue-700 px-4 font-bold text-white sm:block"><Plus className="mr-2 inline" size={17}/>{config.create}</button></header>
    {state==='loading'&&<div aria-live="polite" className="grid min-h-48 place-items-center rounded-3xl border bg-white"><Loader2 className="animate-spin text-blue-700"/><span className="sr-only">Loading {config.title}</span></div>}
    {state==='error'&&<div role="alert" className="rounded-3xl border border-red-200 bg-red-50 p-6"><h3 className="font-bold text-red-900">{config.title} could not load</h3><p className="mt-2 text-sm text-red-800">{error}</p><button onClick={load} className="mt-4 min-h-11 rounded-xl border border-red-300 px-4 font-semibold"><RefreshCw className="mr-2 inline" size={16}/>Retry</button></div>}
    {state==='ready'&&page.items.length===0&&<div className="rounded-3xl border border-dashed border-slate-300 bg-white px-6 py-16 text-center"><CalendarDays className="mx-auto text-blue-700"/><h3 className="mt-4 text-lg font-bold">{config.empty}</h3><p className="mt-2 text-sm text-slate-500">Create the first record when client care requires it.</p></div>}
    {state==='ready'&&page.items.length>0&&<div className="space-y-6">{Object.entries(grouped).map(([status,items])=><section key={status}><h3 className="mb-3 text-sm font-bold uppercase tracking-wider text-slate-500">{status.replaceAll('_',' ')}</h3><div className="grid gap-3 lg:grid-cols-2">{items.map(item=><article key={item.id} className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><div className="flex items-start justify-between gap-3"><div><p className="font-bold">{item.title}</p><p className="mt-1 text-sm text-slate-500">{item.type.replaceAll('_',' ')}</p></div><span className="rounded-full bg-blue-50 px-2.5 py-1 text-xs font-bold text-blue-700">{item.status.replaceAll('_',' ')}</span></div>{item.due_at&&<p className="mt-4 text-sm text-slate-600">Due {new Date(item.due_at).toLocaleString()}</p>}{!['COMPLETED','CANCELLED'].includes(item.status)&&<button onClick={async()=>{await updatePracticeResource(config.resource,item.id,{version:item.version,status:'COMPLETED'});await load();}} className="mt-4 min-h-11 w-full rounded-xl border border-slate-200 font-semibold text-slate-800"><CheckCircle2 className="mr-2 inline" size={16}/>Mark complete</button>}</article>)}</div></section>)}</div>}
    <button onClick={()=>setOpen(true)} className="fixed inset-x-4 bottom-[calc(5rem+env(safe-area-inset-bottom))] z-20 min-h-12 rounded-xl bg-blue-700 font-bold text-white shadow-lg sm:hidden"><Plus className="mr-2 inline" size={17}/>{config.create}</button>
    {open&&<CreateOperation config={config} clients={clients} onClose={()=>setOpen(false)} onSaved={async()=>{setOpen(false);await load();}}/>}
  </div>;
}

function CreateOperation({config,clients,onClose,onSaved}){const [form,setForm]=useState({client_id:clients[0]?.id||'',title:'',due_at:''});const [busy,setBusy]=useState(false);const [error,setError]=useState('');async function submit(event){event.preventDefault();setBusy(true);setError('');try{await createPracticeResource(config.resource,{client_id:form.client_id,type:config.type,title:form.title,status:config.status,due_at:form.due_at||null,payload:{source:'CONSULTANT_ENTERED'}});await onSaved();}catch(reason){setError(reason.message);setBusy(false);}}return <div className="fixed inset-0 z-50 flex items-end bg-slate-950/45 sm:items-stretch sm:justify-end" onClick={onClose}><form onSubmit={submit} onClick={event=>event.stopPropagation()} role="dialog" aria-modal="true" aria-labelledby="operation-title" className="max-h-[90vh] w-full overflow-y-auto rounded-t-3xl bg-white p-5 pb-[calc(1.25rem+env(safe-area-inset-bottom))] sm:h-full sm:max-h-none sm:max-w-md sm:rounded-none sm:p-8"><h2 id="operation-title" className="text-2xl font-bold">{config.create}</h2><p className="mt-2 text-sm text-slate-500">Only authorised clients in this workspace are available.</p>{error&&<p role="alert" className="mt-4 rounded-xl bg-red-50 p-3 text-sm text-red-700">{error}</p>}<label className="mt-6 block text-sm font-semibold">Client<select required value={form.client_id} onChange={event=>setForm({...form,client_id:event.target.value})} className="mt-2 min-h-12 w-full rounded-xl border px-3"><option value="">Select client</option>{clients.map(client=><option key={client.id} value={client.id}>{client.displayName}</option>)}</select></label><label className="mt-5 block text-sm font-semibold">Title<input required value={form.title} onChange={event=>setForm({...form,title:event.target.value})} className="mt-2 min-h-12 w-full rounded-xl border px-3"/></label><label className="mt-5 block text-sm font-semibold">Date and time<input type="datetime-local" value={form.due_at} onChange={event=>setForm({...form,due_at:event.target.value})} className="mt-2 min-h-12 w-full rounded-xl border px-3"/></label><div className="sticky bottom-0 mt-8 flex gap-3 bg-white py-3"><button type="button" onClick={onClose} className="min-h-12 flex-1 rounded-xl border font-semibold">Cancel</button><button disabled={busy} className="min-h-12 flex-1 rounded-xl bg-blue-700 font-bold text-white disabled:opacity-50">{busy?'Saving…':'Save'}</button></div></form></div>}
